func (a *AntigravityAgent) DetectPresence(ctx context.Context) (bool, error) {
    repoRoot, err := paths.WorktreeRoot(ctx)
    if err != nil { repoRoot = "." }
    // Antigravity writes runtime data to .gemini/jetski/; user hooks live in .agents/.
    for _, candidate := range []string{
        filepath.Join(repoRoot, ".agents"),
        filepath.Join(repoRoot, ".gemini", "jetski"),
    } {
        if _, err := os.Stat(candidate); err == nil { return true, nil }
    }
    return false, nil
}

