```go
package antigravity

import (
    "context"
    "encoding/json"
    "errors"
    "io"
    "time"

    "github.com/entireio/cli/cmd/entire/cli/agent"
    "github.com/entireio/cli/cmd/entire/cli/strategy"
)

func (a *AntigravityAgent) HookNames() []string {
    return []string{
        HookNamePreToolUse, HookNamePostToolUse,
        HookNamePreInvocation, HookNamePostInvocation, HookNameStop,
    }
}

func (a *AntigravityAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
    switch hookName {
    case HookNamePreInvocation:
        return a.parsePreInvocation(ctx, stdin)
    case HookNamePostInvocation:
        return a.parsePostInvocation(ctx, stdin)
    case HookNameStop:
        return a.parseStop(ctx, stdin)
    case HookNamePreToolUse:
        return a.parsePreToolUse(ctx, stdin)
    case HookNamePostToolUse:
        return nil, nil //nolint:nilnil // file capture happens on pre-tool-use
    default:
        return nil, nil //nolint:nilnil // unknown verb = no-op
    }
}

func (a *AntigravityAgent) parsePreInvocation(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
    var p PreInvocationPayload
    if err := json.NewDecoder(stdin).Decode(&p); err != nil { return nil, err }

    // First-ever invocation? Session state not yet created → emit SessionStart;
    // framework's SessionStart handler runs strategy.InitializeSession.
    eventType := agent.TurnStart
    if _, err := strategy.LoadSessionState(ctx, p.ConversationID); errors.Is(err, strategy.ErrStateNotFound) {
        eventType = agent.SessionStart
    } else if err != nil {
        return nil, err
    }
    return &agent.Event{
        Type:       eventType,
        SessionID:  p.ConversationID,
        SessionRef: p.TranscriptPath,
        Timestamp:  time.Now(),
    }, nil
}

func (a *AntigravityAgent) parsePostInvocation(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
    var p PostInvocationPayload
    if err := json.NewDecoder(stdin).Decode(&p); err != nil { return nil, err }
    return &agent.Event{
        Type: agent.TurnEnd, SessionID: p.ConversationID,
        SessionRef: p.TranscriptPath, Timestamp: time.Now(),
    }, nil
}

func (a *AntigravityAgent) parseStop(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
    var p StopPayload
    if err := json.NewDecoder(stdin).Decode(&p); err != nil { return nil, err }
    if !p.FullyIdle {
        return nil, nil //nolint:nilnil // background tasks live; do not finalize
    }
    return &agent.Event{
        Type: agent.SessionEnd, SessionID: p.ConversationID,
        SessionRef: p.TranscriptPath, Timestamp: time.Now(),
    }, nil
}

func (a *AntigravityAgent) parsePreToolUse(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
    var p PreToolUsePayload
    if err := json.NewDecoder(stdin).Decode(&p); err != nil { return nil, err }
    modified, newFiles := extractFilePaths(p.ToolCall)
    if len(modified) == 0 && len(newFiles) == 0 {
        return nil, nil //nolint:nilnil // non-mutating tool
    }
    return &agent.Event{
        Type: agent.ToolUse, SessionID: p.ConversationID, SessionRef: p.TranscriptPath,
        ModifiedFiles: modified, NewFiles: newFiles, Timestamp: time.Now(),
    }, nil
}

// extractFilePaths inspects toolCall.Args for the three mutating tools.
// Returns (modified, new) — `write_to_file` with Overwrite=false → newFiles; else modified.
func extractFilePaths(tc ToolCall) (modified, newFiles []string) {
    switch tc.Name {
    case "write_to_file":
        var a struct{ TargetFile string; Overwrite bool }
        _ = json.Unmarshal(tc.Args, &a)
        if a.TargetFile == "" { return }
        if a.Overwrite { return []string{a.TargetFile}, nil }
        return nil, []string{a.TargetFile}
    case "replace_file_content", "multi_replace_file_content":
        var a struct{ TargetFile string }
        _ = json.Unmarshal(tc.Args, &a)
        if a.TargetFile != "" { return []string{a.TargetFile}, nil }
    }
    return
}

// WriteHookResponse fulfills the HookSupport contract for emitting stdout JSON
// back to Antigravity. For most hooks we emit nothing; for Stop we must always
// emit a "decision" field (REQUIRED per /tmp/ag-hooks.md:379). When the framework
// decides to allow the stop (no condense-in-flight, etc.), we emit `{"decision":"stop"}`.
func (a *AntigravityAgent) WriteHookResponse(message string) error { /* same shape as geminicli's WriteHookResponse */ }
