func (a *AntigravityAgent) parsePreInvocation(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
    var p PreInvocationPayload
    if err := json.NewDecoder(stdin).Decode(&p); err != nil { return nil, err }
    // Always emit TurnStart. The framework's TurnStart handler
    // (cli/lifecycle.go:406) calls strategy.InitializeSession, which is
    // idempotent — first arrival creates state, subsequent arrivals reuse it.
    return &agent.Event{
        Type:       agent.TurnStart,
        SessionID:  p.ConversationID,
        SessionRef: p.TranscriptPath,
        Timestamp:  time.Now(),
    }, nil
}

