// WriteHookResponse writes a JSON message to stdout for Antigravity to consume.
// Mirrors geminicli's implementation. Callers must supply a JSON-shaped string.
//
// For hook events with no stdout response (PreToolUse `allow`-by-default, all
// other non-Stop events), the framework passes an empty message which we skip.
// For Stop: the framework should always pass `{"decision":"stop"}` (REQUIRED
// per /tmp/ag-hooks.md:379); v1 never returns `{"decision":"continue"}` because
// nothing in the lifecycle handlers can decide to override Antigravity's stop.
// PreToolUse: v1 emits `{"decision":"allow"}` (the framework's default path).
func (a *AntigravityAgent) WriteHookResponse(message string) error {
    if message == "" { return nil }
    if _, err := fmt.Fprintln(os.Stdout, message); err != nil {
        return fmt.Errorf("failed to write hook response: %w", err)
    }
    return nil
}

