func TestInstallHooks_Idempotent(t *testing.T) {
    t.Parallel()
    tmpDir := t.TempDir(); testutil.InitRepo(t, tmpDir); t.Chdir(tmpDir)
    a := &AntigravityAgent{}
    if _, err := a.InstallHooks(context.Background(), false, false); err != nil { t.Fatal(err) }
    n, err := a.InstallHooks(context.Background(), false, false)
    if err != nil { t.Fatal(err) }
    if n != 0 { t.Errorf("re-install returned %d, want 0", n) }
}

func TestInstallHooks_PreservesForeignHooks(t *testing.T) {
    t.Parallel()
    tmpDir := t.TempDir(); testutil.InitRepo(t, tmpDir); t.Chdir(tmpDir)
    foreignPath := filepath.Join(tmpDir, ".agents", "hooks.json")
    _ = os.MkdirAll(filepath.Dir(foreignPath), 0o750)
    foreign := []byte(`{"safety-gate":{"PostToolUse":[{"matcher":"run_command","hooks":[{"command":"./check.sh","timeout":15}]}]}}`)
    if err := os.WriteFile(foreignPath, foreign, 0o600); err != nil { t.Fatal(err) }

    a := &AntigravityAgent{}
    if _, err := a.InstallHooks(context.Background(), false, false); err != nil { t.Fatal(err) }

    data, _ := os.ReadFile(foreignPath)
    var f HooksFile
    if err := json.Unmarshal(data, &f); err != nil { t.Fatal(err) }
    if _, ok := f["entire"]; !ok { t.Error("entire hook missing after install") }
    sg, ok := f["safety-gate"]
    if !ok { t.Fatal("foreign 'safety-gate' was clobbered") }
    if len(sg.PostToolUse) != 1 || sg.PostToolUse[0].Hooks[0].Command != "./check.sh" || sg.PostToolUse[0].Hooks[0].Timeout != 15 {
        t.Errorf("foreign hook altered: %+v", sg)
    }
}

func TestUninstallHooks_LeavesForeignHooks(t *testing.T) {
    t.Parallel()
    tmpDir := t.TempDir(); testutil.InitRepo(t, tmpDir); t.Chdir(tmpDir)
    foreignPath := filepath.Join(tmpDir, ".agents", "hooks.json")
    _ = os.MkdirAll(filepath.Dir(foreignPath), 0o750)
    _ = os.WriteFile(foreignPath, []byte(`{"safety-gate":{"Stop":[{"command":"./bye.sh"}]}}`), 0o600)
    a := &AntigravityAgent{}
    if _, err := a.InstallHooks(context.Background(), false, false); err != nil { t.Fatal(err) }
    if err := a.UninstallHooks(context.Background()); err != nil { t.Fatal(err) }
    data, _ := os.ReadFile(foreignPath)
    var f HooksFile
    _ = json.Unmarshal(data, &f)
    if _, ok := f["entire"]; ok { t.Error("entire key should be removed") }
    if _, ok := f["safety-gate"]; !ok { t.Error("foreign safety-gate must survive uninstall") }
}

func TestAreHooksInstalled(t *testing.T) {
    t.Parallel()
    tmpDir := t.TempDir(); testutil.InitRepo(t, tmpDir); t.Chdir(tmpDir)
    a := &AntigravityAgent{}
    if a.AreHooksInstalled(context.Background()) { t.Error("fresh repo should report not installed") }
    if _, err := a.InstallHooks(context.Background(), false, false); err != nil { t.Fatal(err) }
    if !a.AreHooksInstalled(context.Background()) { t.Error("should report installed after InstallHooks") }
}

