package antigravity

import (
    "context"
    "os"

    "github.com/entireio/cli/cmd/entire/cli/agent"
)

// Transcript handling for Antigravity. Antigravity writes a JSONL transcript
// to the path supplied via the hook stdin field `transcriptPath` (typically
// <workspace>/.gemini/jetski/transcript.jsonl). The on-disk schema is
// undocumented as of plan-write date; Chunk 3 Task 9 captures a real
// fixture and decides whether to import claudecode's parser, adapt
// geminicli's, or write a fresh one for token/file-change extraction.
