    }
    result, err := agent.RunIsolatedTextGeneratorCLI(ctx, a.CommandRunner, "antigravity", "antigravity", args, prompt)
    if err != nil {
        return "", fmt.Errorf("antigravity text generation failed: %w", err)
    }
    return result, nil
}
